WITH valid AS (SELECT *, ROUND(budget * 0.9, 2) AS budget_adjusted, INITCAP(TRIM(location)) AS location_title, COALESCE(dept_name, 'N/A') AS resolved_dept_name FROM departments WHERE budget >= 3697000) SELECT CASE WHEN budget >= 3258000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, COUNT(DISTINCT dept_name) AS distinct_dept_names, COUNT_IF(dept_name = 'Engineering') AS engineering_events, COUNT(DISTINCT location) AS distinct_locations, ROUND(SUM(budget_adjusted) / NULLIF(COUNT(CASE WHEN location = 'Tokyo' THEN 1 END), 0), 2) AS budget_adjusted_per_tokyo, STDDEV_SAMP(budget) AS budget_stddev FROM valid GROUP BY CUBE (CASE WHEN budget >= 3258000 THEN 'PREMIUM' ELSE 'STANDARD' END)
